def solve():
    n, h, l, r = map(int, input().split())
    a = list(map(int, input().split()))

    # DP[i][j] = maximum number of good sleeps from sleep i onward, given we are at time j
    dp = [[-1] * h for _ in range(n + 1)]

    # Base case: after the last sleep, we have 0 good sleeps
    for j in range(h):
        dp[n][j] = 0

    # Fill DP table from last to first
    for i in range(n - 1, -1, -1):
        for j in range(h):
            # Try both options: sleep after a_i hours or a_i - 1 hours
            for delta in [a[i], a[i] - 1]:
                next_time = (j + delta) % h
                if l <= next_time <= r:
                    # This sleep is good
                    dp[i][j] = max(dp[i][j], 1 + dp[i + 1][next_time])
                else:
                    # This sleep is not good
                    dp[i][j] = max(dp[i][j], dp[i + 1][next_time])

    # Start at time 0
    print(dp[0][0])

solve()
