from collections import defaultdict

def find_components(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            # DFS to find component
            stack = [i]
            visited[i] = True
            component = []
            while stack:
                node = stack.pop()
                component.append(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(component)

    return components

def is_bridge(u, v, graph, visited, component):
    # Check if removing edge u-v disconnects the component
    # We need to check if there's still a path between u and v in the component without this edge

    # Create a copy of the component without this edge
    component_without = [node for node in component if node != u and node != v]

    # Check if u and v are still connected
    if u not in component_without or v not in component_without:
        return True  # One of them is not in the component without this edge

    # DFS to check connectivity
    visited2 = {u: True}
    stack = [u]
    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if neighbor == v:
                continue  # Skip the edge we're removing
            if neighbor not in visited2:
                visited2[neighbor] = True
                stack.append(neighbor)

    return v not in visited2

def solve():
    n = int(input())
    edges = []
    for _ in range(n - 1):
        u, v = map(int, input().split())
        edges.append((u, v))

    components = find_components(n, edges)
    num_components = len(components)

    if num_components == 1:
        print(0)
        return

    # Pick representatives
    reps = [min(c) for c in components]

    # We need to connect all components to the first component
    t = num_components - 1
    print(t)

    # For each component except the first
    for i in range(1, num_components):
        comp = components[i]
        rep = reps[i]

        # Find a non-bridge road in this component
        for u, v in edges:
            if u in comp and v in comp:
                if not is_bridge(u, v, graph, visited, comp):
                    # Close this road
                    print(f"{u} {v} {rep} {reps[0]}")
                    break

solve()
