def longest_path(graph, start, visited):
    max_len = 1
    for neighbor in graph[start]:
        if neighbor not in visited:
            visited.add(neighbor)
            current_len = 1 + longest_path(graph, neighbor, visited)
            max_len = max(max_len, current_len)
            visited.remove(neighbor)
    return max_len

def solve():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    while idx < len(data):
        n = int(data[idx])
        idx += 1

        if n == 0:
            break

        graph = {}
        for _ in range(n):
            a = int(data[idx])
            b = int(data[idx + 1])
            idx += 2

            if a not in graph:
                graph[a] = []
            if b not in graph:
                graph[b] = []
            graph[a].append(b)
            graph[b].append(a)

        max_length = 0
        for node in graph:
            visited = {node}
            length = longest_path(graph, node, visited)
            max_length = max(max_length, length)

        print(max_length)

solve()

