import math

def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2)**2 + (y1 - y2)**2)

def solve():
    N = int(input())
    cities = []
    for _ in range(N):
        x, y, f = map(int, input().split())
        cities.append((x, y, f))

    dp = [0.0] * N
    dp[0] = cities[0][2]  # Start at city 1 (0-indexed)

    for i in range(1, N):
        max_happiness = -float('inf')
        for j in range(i):
            # Happiness from going from city j to city i
            happiness = dp[j] + cities[i][2] - distance(cities[j][0], cities[j][1], cities[i][0], cities[i][1])
            if happiness > max_happiness:
                max_happiness = happiness
        dp[i] = max_happiness

    print(f"{dp[N-1]:.6f}")

solve()
