# Split into words
words = []
i = 0
while i < len(s):
    if s[i] in ',;':
        i += 1
    else:
        j = i
        while j < len(s) and s[j] not in ',;':
            j += 1
        words.append(s[i:j])
        i = j

# Identify number words
number_words = []
non_number_words = []

for word in words:
    if word == "0":
        number_words.append(word)
    elif word and word.isdigit() and not word.startswith('0'):
        number_words.append(word)
    else:
        non_number_words.append(word)

# Build strings
a = ",".join(number_words)
b = ",".join(non_number_words)

# Print results
if a:
    print(f'"{a}"')
else:
    print("-")

if b:
    print(f'"{b}"')
else:
    print("-")
