for i in range(n):
    name, points = input().split()
    points = int(points)

    # Update participant's points
    if name in participants:
        participants[name] += points
    else:
        participants[name] = points

    # Track max points
    if participants[name] > max_points:
        max_points = participants[name]

    # Track when each participant reached max points
    if participants[name] == max_points:
        tie_breaker[name] = i + 1  # 1-indexed round number

