    if winner is None or participants[name] > participants[winner]:
        winner = name
    elif participants[name] == participants[winner]:
        # Tie - choose the one who reached max points first
        if name not in tie_breaker:
            winner = name
        elif winner not in tie_breaker:
            winner = name
        elif tie_breaker[name] < tie_breaker[winner]:
            winner = name

print(winner)
