def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        cities = [input().strip() for _ in range(n)]

        # Precompute overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    max_overlap = 0
                    for k in range(min(len(cities[i]), len(cities[j]))):
                        if cities[i][-k-1] == cities[j][k]:
                            max_overlap += 1
                        else:
                            break
                    overlap[i][j] = max_overlap

        # DP: dp[mask][i] = shortest length ending with city i
        dp = [[float('inf')] * n for _ in range(1 << n)]

        # Initialize with each city alone
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # DP transition
        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue

                for j in range(n):
                    if mask & (1 << j):
                        continue

                    new_mask = mask | (1 << j)
                    new_len = dp[mask][i] + len(cities[j]) - overlap[i][j]
                    if new_len < dp[new_mask][j]:
                        dp[new_mask][j] = new_len

        # Find the minimum length
        min_len = min(dp[(1 << n) - 1][i] for i in range(n))
        print(min_len)

solve()
