import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Use sliding window to find minimal by inclusion segment
    count = {}
    distinct = 0
    l = 0
    result = -1, -1

    for r in range(n):
        # Add a[r] to the window
        if a[r] in count:
            count[a[r]] += 1
        else:
            count[a[r]] = 1
            distinct += 1

        # If we have more than k distinct elements, move left pointer
        while distinct > k:
            count[a[l]] -= 1
            if count[a[l]] == 0:
                del count[a[l]]
                distinct -= 1
            l += 1

        # If we have exactly k distinct elements, check minimality
        if distinct == k:
            # Check if this window is minimal by inclusion
            is_minimal = True
            for i in range(l, r + 1):
                # Try removing element at position i
                temp_count = count.copy()
                temp_distinct = distinct

                if temp_count[a[i]] == 1:
                    temp_distinct -= 1
                else:
                    temp_count[a[i]] -= 1

                if temp_distinct < k:
                    is_minimal = False
                    break

            if is_minimal:
                result = l + 1, r + 1
                return

    print(f"{result[0]} {result[1]}")

if __name__ == "__main__":
    solve()
