    u, v = map(int, input().split())
    friends[u].add(v)
    friends[v].add(u)

q = int(input())
for _ in range(q):
    query = list(map(int, input().split()))
    if query[0] == 1:
        u, v = query[1], query[2]
        friends[u].add(v)
        friends[v].add(u)
    elif query[0] == 2:
        u, v = query[1], query[2]
        friends[u].remove(v)
        friends[v].remove(u)
    else:
        # Process
        # We need to process in decreasing order of power
        # Start with all nobles alive
        current_alive = set(alive)
        while True:
            # Find vulnerable nobles
            vulnerable = []
            for noble in current_alive:
                # Check if all friends have higher power
                all_higher = True
                for friend in friends[noble]:
                    if friend in current_alive and friend <= noble:
                        all_higher = False
                        break
                if all_higher:
                    vulnerable.append(noble)

            if not vulnerable:
                break

            # Kill vulnerable nobles
            for noble in vulnerable:
                current_alive.remove(noble)

        print(len(current_alive))
