# Check if we can get exactly x points
def can_get_points():
    # Submit neither problem
    if x == 0:
        return True

    # Submit only the first problem
    for i in range(t):
        if a - i * da == x:
            return True

    # Submit only the second problem
    for i in range(t):
        if b - i * db == x:
            return True

    # Submit both problems at the same minute
    for i in range(t):
        total = (a - i * da) + (b - i * db)
        if total == x:
            return True

    # Submit the first problem at minute i and the second at minute j (i != j)
    for i in range(t):
        for j in range(t):
            if i != j:
                total = (a - i * da) + (b - j * db)
                if total == x:
                    return True

    return False

if can_get_points():
    print("YES")
else:
    print("NO")
