n = int(input())
a = list(map(int, input().split()))

# Build adjacency list
adj = [[] for _ in range(n)]
for i in range(n):
    for j in range(i + 1, n):
        if a[i] & a[j]:
            adj[i].append(j)
            adj[j].append(i)

# Check for cycles
min_cycle_length = float('inf')

# Check for 3-length cycles (triangles)
for i in range(n):
    neighbors = adj[i]
    if len(neighbors) < 2:
        continue
    # Check all pairs of neighbors
    for j in range(len(neighbors)):
        for k in range(j + 1, len(neighbors)):
            if a[neighbors[j]] & a[neighbors[k]]:
                # Check if i, neighbors[j], neighbors[k] form a cycle
                if a[i] & a[neighbors[j]] and a[neighbors[j]] & a[neighbors[k]] and a[neighbors[k]] & a[i]:
                    min_cycle_length = min(min_cycle_length, 3)

# Check for 4-length cycles
for i in range(n):
    neighbors = adj[i]
    if len(neighbors) < 3:
        continue
    for j in range(len(neighbors)):
        for k in range(j + 1, len(neighbors)):
            for l in range(k + 1, len(neighbors)):
                if a[neighbors[j]] & a[neighbors[k]] and a[neighbors[k]] & a[neighbors[l]] and a[neighbors[l]] & a[neighbors[j]]:
                    # Check if i, neighbors[j], neighbors[k], neighbors[l] form a cycle
                    if a[i] & a[neighbors[j]] and a[neighbors[k]] & a[i] and a[neighbors[l]] & a[i]:
                        min_cycle_length = min(min_cycle_length, 4)

if min_cycle_length == float('inf'):
    print(-1)
else:
    print(min_cycle_length)
