import sys
import math

def modinv(a, m):
    """Modular inverse using Fermat's little theorem"""
    return pow(a, m - 2, m)

def comb(n, k, mod, fact, inv_fact):
    """Compute combination C(n, k) modulo mod"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

# Precompute factorials and inverse factorials modulo 10^9+7
MOD = 10**9 + 7
MAX = 10**5 + 1
fact = [1] * MAX
inv_fact = [1] * MAX
for i in range(1, MAX):
    fact[i] = fact[i-1] * i % MOD
inv_fact[MAX-1] = modinv(fact[MAX-1], MOD)
for i in range(MAX-2, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

# Precompute Möbius function for all numbers up to 10^5
mu = [1] * (MAX)
min_prime = [0] * (MAX)
for i in range(2, MAX):
    if min_prime[i] == 0:
        min_prime[i] = i
        for j in range(i*i, MAX, i):
            if min_prime[j] == 0:
                min_prime[j] = i

for i in range(2, MAX):
    if min_prime[i] == i:
        # i is prime
        mu[i] = -1
    else:
        # i has a prime factor
        p = min_prime[i]
        if i // p % p == 0:
            # i has p^2 as a factor
            mu[i] = 0
        else:
            # i has p as a factor but not p^2
            mu[i] = mu[i // p]

# Read input
q = int(sys.stdin.readline())
for _ in range(q):
    n, f = map(int, sys.stdin.readline().split())

    if f > n:
        print(0)
        continue

    # Compute answer
    ans = 0
    for d in range(1, n + 1):
        if n % d == 0:
            # d is a divisor of n
            c = comb(n // d - 1, f - 1, MOD, fact, inv_fact)
            ans = (ans + mu[d] * c) % MOD

    print(ans)
"}

